using System.Text;using HealthTracker.Api.Data;using HealthTracker.Api.Services;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;using Microsoft.OpenApi.Models;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddControllers();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen(o=>{o.AddSecurityDefinition("Bearer",new OpenApiSecurityScheme{Type=SecuritySchemeType.Http,Scheme="bearer",BearerFormat="JWT",In=ParameterLocation.Header});o.AddSecurityRequirement(new OpenApiSecurityRequirement{{new OpenApiSecurityScheme{Reference=new OpenApiReference{Type=ReferenceType.SecurityScheme,Id="Bearer"}},Array.Empty<string>()}});});builder.Services.AddDbContext<AppDbContext>(o=>o.UseInMemoryDatabase("HealthTrackerDb"));builder.Services.AddApplicationServices();builder.Services.AddScoped<ITokenService,TokenService>();builder.Services.AddScoped<IAuthService,AuthService>();builder.Services.AddScoped<IDoseService,DoseService>();var jwtKey=builder.Configuration["Jwt:Key"]??"CHANGE_ME_TO_A_LONG_RANDOM_PRODUCTION_SECRET_32_CHARS";builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=true,ValidateAudience=true,ValidateLifetime=true,ValidateIssuerSigningKey=true,ValidIssuer=builder.Configuration["Jwt:Issuer"]??"HealthTracker",ValidAudience=builder.Configuration["Jwt:Audience"]??"HealthTrackerWeb",IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey))});builder.Services.AddAuthorization();builder.Services.AddCors(o=>o.AddPolicy("web",p=>p.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod()));var app=builder.Build();if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();}app.UseCors("web");app.UseAuthentication();app.UseAuthorization();app.MapControllers();app.MapGet("/api/health",()=>Results.Ok(new{status="ok"}));app.Run();